const ICONS={home:'<path d="m3 10 9-7 9 7v10H15v-7H9v7H3z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1Zm0 0v15"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4z"/>',cards:'<rect x="6" y="7" width="15" height="14" rx="2"/><path d="M17 3H5a2 2 0 0 0-2 2v12m8-5h5m-5 4h5"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',left:'<path d="m14 5-7 7 7 7"/>',right:'<path d="m10 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',print:'<path d="M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z"/>',shuffle:'<path d="M3 6h3l12 12h3m-4-4 4 4-4 4M3 18h3l5-5m2-2 5-5h3m-4-4 4 4-4 4"/>',flip:'<path d="M20 7a8 8 0 1 0 0 10M20 3v5h-5"/>',link:'<path d="m9 15 6-6m-5-4 2-2a5 5 0 0 1 7 7l-2 2m-3 7-2 2a5 5 0 0 1-7-7l2-2"/>',note:'<path d="M4 3h16v18H4zM8 7h8M8 11h8M8 15h5"/>',compare:'<path d="M3 4h7v16H3zM14 4h7v16h-7z"/>',expand:'<path d="M4 9V4h5m6 0h5v5M4 15v5h5m6 0h5v-5"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="8" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',flag:'<path d="M5 22V3m0 0c6-5 8 5 14 0v11c-6 5-8-5-14 0"/>'};
const ico=n=>'<svg viewBox="0 0 24 24" aria-hidden="true">'+(ICONS[n]||ICONS.book)+'</svg>';
function avatar(g){return '<svg class="avatar-svg" viewBox="0 0 160 160" aria-hidden="true"><circle cx="80" cy="80" r="79" fill="#E7DDC9"/>'+ (g==='female'?'<path d="M45 80V54c0-46 72-44 72 0v40H43z" fill="#3E5B6C"/>':'<path d="M47 62V47c0-36 65-40 68 4v19H47z" fill="#3E5B6C"/>')+'<path d="M67 88v20h26V88" fill="#D0BB93"/><path d="M29 151v-21c0-24 23-32 39-32h24c18 0 39 8 39 32v21" fill="'+(g==='female'?'#59798F':'#3E5B6C')+'"/><path d="m65 98 15 31 16-31" fill="#FFFFFF"/><path d="m62 99-9 16 16 11-6 24h34l-6-24 16-11-9-16-18 34z" fill="'+(g==='female'?'#3E5B6C':'#59798F')+'"/>'+ (g==='female'?'<path d="m77 105-7 15 11-1 10 6-6-20" fill="#C4AA78"/>':'<path d="m76 105 8 0 3 8-7 28-7-28z" fill="#C4AA78"/>')+'<ellipse cx="80" cy="62" rx="29" ry="35" fill="#DCCCAE"/><path d="M50 52c5-28 56-43 61 2-11-6-19-14-26-22-7 14-20 19-35 20" fill="#3E5B6C"/><circle cx="68" cy="64" r="2.5" fill="#212121"/><circle cx="92" cy="64" r="2.5" fill="#212121"/><path d="M71 80q9 7 18 0" fill="none" stroke="#9F8668" stroke-width="2.5" stroke-linecap="round"/>'+ (g==='female'?'<circle cx="51" cy="74" r="3" fill="#C4AA78"/><circle cx="109" cy="74" r="3" fill="#C4AA78"/>':'')+'<rect x="107" y="125" width="12" height="4" rx="1" fill="#C4AA78"/></svg>'}
const KEY='ipag-glossary-v2',COLORS={yellow:'Vàng',green:'Xanh lá',blue:'Xanh dương',pink:'Hồng',purple:'Tím',orange:'Cam'};
let storageOK=true,raw={};try{raw=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch(e){storageOK=false}if(typeof raw!=='object'||Array.isArray(raw))raw={};
const cleanIds=a=>Array.isArray(a)?a.filter(x=>termIds.has(x)):[];
let profile=raw.profile&&typeof raw.profile.fullName==='string'&&['male','female'].includes(raw.profile.avatar)?{fullName:raw.profile.fullName.trim().replace(/\s+/g,' ').slice(0,80),avatar:raw.profile.avatar}:null;
let bookmarks=new Set(cleanIds(raw.bookmarks)),read=new Set(cleanIds(raw.read)),known=new Set(cleanIds(raw.known)),recent=cleanIds(raw.recent||(raw.last?[raw.last]:[])).slice(0,12);
let notes={},highlights={};for(const id of termIds){notes[id]=Array.isArray(raw.notes?.[id])?raw.notes[id].filter(n=>n&&typeof n.id==='string'&&typeof n.text==='string').map(n=>({...n,text:n.text.slice(0,10000),quote:typeof n.quote==='string'?n.quote:''})):[];highlights[id]=Array.isArray(raw.highlights?.[id])?raw.highlights[id].filter(h=>h&&typeof h.id==='string'&&Object.hasOwn(COLORS,h.color)&&Number.isInteger(h.start)&&Number.isInteger(h.end)&&h.start>=0&&h.end>h.start&&termMap.get(id).paragraphs.some(p=>p.index===h.p&&h.end<=p.text.length)).map(h=>({...h,quote:termMap.get(id).paragraphs.find(p=>p.index===h.p).text.slice(h.start,h.end)})):[]}
let settings={audio:raw.settings?.audio===true,haptics:raw.settings?.haptics!==false,motion:raw.settings?.motion!==false,collapsed:raw.settings?.collapsed===true};let studyDays=Array.isArray(raw.studyDays)?raw.studyDays.filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x)):[];
const name=()=>profile?.fullName.split(/\s+/).at(-1)||'bạn';let toastTimer;
function toast(s){$('toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').textContent='',3600)}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({profile,bookmarks:[...bookmarks],read:[...read],known:[...known],recent,last:recent[0]||null,notes,highlights,settings,studyDays}));storageOK=true;return true}catch(e){storageOK=false;toast('Trình duyệt chưa lưu được thay đổi. Dữ liệu chỉ còn trong phiên đang mở.');return false}}
const uid=()=>Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,8);
let s={view:'home',q:'',section:'all',alpha:'all',sort:'source',selected:null,savedFilter:'all',depth:0,scroll:0,listScroll:0,detailScroll:0};let draft='',suggestIndex=-1,selectionParts=[],modalContext=null,busy=false;
const VIEWS=[['home','home','Trang chủ'],['lookup','search','Tra cứu'],['reading','book','Đọc theo phần'],['saved','bookmark','Đã lưu & ghi chú'],['compare','compare','So sánh'],['study','cards','Tự ôn']];
const mobile=()=>window.innerWidth<=680;const reduced=()=>!settings.motion||window.matchMedia('(prefers-reduced-motion: reduce)').matches;
function hashState(){let h='';try{h=decodeURIComponent(location.hash.slice(1))}catch(e){}if(termIds.has(h))return{view:'lookup',selected:h};if(VIEWS.some(v=>v[0]===h))return{view:h};if(h.startsWith('part-')&&DATA.sections.some(x=>x.id===h.slice(5)))return{view:'lookup',section:h.slice(5)};return{view:'home'}}
function currentHash(){return s.selected&&['lookup','saved'].includes(s.view)?s.selected:s.view}
function rememberHistory(){s.scroll=window.scrollY;s.listScroll=$('term-list')?.scrollTop||0;s.detailScroll=$('detail')?.scrollTop||0;try{history.replaceState({ipag:true,s:{...s}},'','#'+currentHash())}catch(e){}}
function go(patch,{replace=false,restore=false}={}){if(!replace)rememberHistory();s={...s,...patch,depth:replace?s.depth:s.depth+1};if(!restore){s.scroll=0;s.listScroll=0;s.detailScroll=0}selectionParts=[];draft=s.q;try{history[replace?'replaceState':'pushState']({ipag:true,s:{...s}},'','#'+currentHash())}catch(e){}render();if(restore)restoreScroll();else window.scrollTo({top:0,behavior:'instant'})}
function navigate(view){if(view==='study')startSession(false);go({view,q:'',section:'all',alpha:'all',selected:null,savedFilter:'all'})}
function restoreScroll(){requestAnimationFrame(()=>{window.scrollTo({top:s.scroll||0,behavior:'instant'});if($('term-list'))$('term-list').scrollTop=s.listScroll||0;if($('detail'))$('detail').scrollTop=s.detailScroll||0})}
function back(){if(s.depth>0)history.back();else go({view:'lookup',selected:null,q:'',section:'all',alpha:'all'},{replace:true})}
function openTerm(id){if(!termIds.has(id))return;recent=[id,...recent.filter(x=>x!==id)].slice(0,12);persist();go({view:['lookup','saved'].includes(s.view)?s.view:'lookup',selected:id});if(!mobile())requestAnimationFrame(()=>$('detail-title')?.focus({preventScroll:true}))}
function levenshtein(a,b){let prev=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){let row=[i];for(let j=1;j<=b.length;j++)row[j]=Math.min(row[j-1]+1,prev[j]+1,prev[j-1]+(a[i-1]===b[j-1]?0:1));prev=row}return prev[b.length]}
const searchIndex=DATA.terms.map((t,index)=>({t,index,key:fold(t.key).trim(),title:fold(t.title),titleWords:words(t.title),body:fold(t.paragraphs.map(p=>p.text).join(' ')),bodyWords:new Set(words(t.paragraphs.map(p=>p.text).join(' ')))}));
function searchRank(q){q=fold(q).trim().replace(/\s+/g,' ');const qs=words(q);if(!qs.length)return searchIndex.map(x=>({...x,tier:99,label:''}));const out=[];for(const x of searchIndex){let tier=Infinity,label='';if(x.key===q){tier=0;label='Đúng thuật ngữ'}else if((' '+x.titleWords.join(' ')+' ').includes(' '+qs.join(' ')+' ')){tier=1;label='Khớp tiêu đề'}else if(qs.every(w=>x.titleWords.includes(w))){tier=2;label='Khớp tiêu đề'}else if(qs.every(w=>x.titleWords.some(t=>t.startsWith(w)))){tier=3;label='Khớp đầu từ'}else if(q.length>=3&&qs.every(w=>x.title.includes(w))){tier=4;label='Trong tiêu đề'}else if(qs.every(w=>w.length>=4&&x.titleWords.some(t=>Math.abs(t.length-w.length)<=2&&levenshtein(t,w)<=(w.length>=7?2:1)))){tier=5;label='Gợi ý gần đúng'}else if(qs.every(w=>x.bodyWords.has(w))){tier=6;label='Trong giải thích'}else if(qs.every(w=>w.length<3?x.bodyWords.has(w):x.body.includes(w))){tier=7;label='Trong giải thích'}if(Number.isFinite(tier))out.push({...x,tier,label})}return out.sort((a,b)=>a.tier-b.tier||a.index-b.index)}
function hasSaved(id){return bookmarks.has(id)||notes[id].length>0||highlights[id].length>0}
function results(){let r=searchRank(s.q).filter(x=>(s.section==='all'||x.t.section===s.section)&&(s.alpha==='all'||(s.alpha==='#'?/^\d/.test(x.t.key):fold(x.t.key).startsWith(s.alpha.toLowerCase()))));if(s.view==='saved')r=r.filter(x=>hasSaved(x.t.id)&&(s.savedFilter==='all'||s.savedFilter==='bookmarks'&&bookmarks.has(x.t.id)||s.savedFilter==='notes'&&notes[x.t.id].length||s.savedFilter==='highlights'&&highlights[x.t.id].length));if(!s.q.trim()&&s.sort==='az')r.sort((a,b)=>a.t.key.localeCompare(b.t.key,'vi'));return r}
function searchRanges(text,q){const f=fold(text),ranges=[];for(const w of [...new Set(words(q))].sort((a,b)=>b.length-a.length)){let at=0;while((at=f.indexOf(w,at))!==-1){const before=f[at-1]||'',after=f[at+w.length]||'';if(w.length>=3||!/[a-z0-9]/.test(before)&&!/[a-z0-9]/.test(after))ranges.push({start:at,end:at+w.length});at+=w.length}}return ranges}
function simpleHighlight(text,q=s.q){const rs=searchRanges(text,q);let out='',last=0;const merged=[];for(const r of rs.sort((a,b)=>a.start-b.start)){const p=merged.at(-1);if(p&&r.start<=p.end)p.end=Math.max(p.end,r.end);else merged.push({...r})}for(const r of merged){out+=esc(text.slice(last,r.start))+'<mark>'+esc(text.slice(r.start,r.end))+'</mark>';last=r.end}return out+esc(text.slice(last))}
const linkCandidates=DATA.terms.slice().sort((a,b)=>b.key.length-a.key.length);
function linkedRanges(text,currentId){const rs=[],f=fold(text);for(const t of linkCandidates){if(t.id===currentId||t.key.length<2)continue;const k=fold(t.key);let at=0;while((at=f.indexOf(k,at))!==-1){const end=at+k.length;if(!/[a-z0-9]/.test(f[at-1]||'')&&!/[a-z0-9]/.test(f[end]||'')&&!rs.some(r=>at<r.end&&end>r.start))rs.push({start:at,end,id:t.id});at=end}}return rs}
function para(p,{id=null,links=false,query='',annotations=false}={}){const text=p.text,hs=annotations?(highlights[id]||[]).filter(h=>h.p===p.index):[],ls=links?linkedRanges(text,id):[],qs=query?searchRanges(text,query):[],styles=[];let pos=0;for(const r of p.runs||[]){styles.push({start:pos,end:pos+r.text.length,bold:r.bold,italic:r.italic});pos+=r.text.length}const cuts=new Set([0,text.length]);for(const r of [...hs,...ls,...qs,...styles]){cuts.add(r.start);cuts.add(r.end)}const ends=[...cuts].filter(n=>n>=0&&n<=text.length).sort((a,b)=>a-b);let out='';for(let i=0;i<ends.length-1;i++){const a=ends[i],b=ends[i+1];let v=esc(text.slice(a,b));const st=styles.find(r=>a>=r.start&&b<=r.end);if(st?.bold)v='<strong>'+v+'</strong>';if(st?.italic)v='<em>'+v+'</em>';const link=ls.find(r=>a>=r.start&&b<=r.end);if(link)v='<button type="button" class="term-link" data-term="'+link.id+'" title="Tra cứu '+esc(termMap.get(link.id).key)+'">'+v+'</button>';if(qs.some(r=>a>=r.start&&b<=r.end))v='<mark class="query-match">'+v+'</mark>';const hl=hs.filter(r=>a>=r.start&&b<=r.end).at(-1);if(hl)v='<mark class="user-highlight '+hl.color+'" data-hlid="'+hl.id+'">'+v+'</mark>';out+=v}return '<p class="source-p'+(/^(Câu tự hỏi|Trả lời câu hỏi):/.test(text)?' question':'')+'" data-source-index="'+p.index+'" '+(annotations?'data-annotatable="'+p.index+'"':'')+'>'+out+'</p>'}
function sourceHTML(){let out='';for(const p of DATA.source){const term=termMap.get('term-'+p.index);if(p.index===0)out+='<h1 class="doc-head" data-source-index="0">'+esc(p.text)+'</h1>';else if(p.text.startsWith('PHẦN '))out+='<h2 id="source-'+p.index+'" data-source-index="'+p.index+'">'+esc(p.text)+'</h2>';else if(term||[1,8,13].includes(p.index))out+='<h3 id="source-'+p.index+'" data-source-index="'+p.index+'">'+esc(p.text)+'</h3>';else out+=para(p);if(p.index===13)out+='<table><thead><tr>'+DATA.toc[0].map(c=>'<th scope="col">'+esc(c)+'</th>').join('')+'</tr></thead><tbody>'+DATA.toc.slice(1).map(r=>'<tr>'+r.map(c=>'<td>'+esc(c)+'</td>').join('')+'</tr>').join('')+'</tbody></table>'}return out}
const SOURCE_HTML=sourceHTML();$('print-source').innerHTML=SOURCE_HTML.replace(/ id="source-\d+"/g,'');
