function profileFields(edit=false){return '<label class="field" for="full-name">Họ và tên đầy đủ</label><input class="input" id="full-name" name="fullName" autocomplete="name" maxlength="80" placeholder="Ví dụ: Trương Minh Đức" required value="'+esc(edit?profile?.fullName:'')+'"><p class="field-help">Tên gọi sẽ lấy từ cuối cùng trong họ tên. Ví dụ: Trương Minh Đức → Đức.</p><fieldset class="avatar-options"><legend>Chọn avatar của bạn</legend><div class="avatar-grid">'+[['male','Nam'],['female','Nữ']].map(([v,l])=>'<label class="avatar-option"><input type="radio" name="avatar" value="'+v+'" required '+(edit&&profile?.avatar===v?'checked':'')+'>'+avatar(v)+'<span>'+l+'</span></label>').join('')+'</div></fieldset><p id="profile-error" class="error" role="alert" hidden></p>'}
function gate(){return '<div class="profile-gate"><section class="welcome-art"><img src="'+ASSETS.building+'" alt=""><div><img class="welcome-logo" src="'+ASSETS.logoWhite+'" alt="IPA Group"></div><div><div class="welcome-line"></div><h1>Bộ Từ điển<br>Thuật ngữ của IPAG</h1><p>'+esc(DATA.source.find(p=>p.index===3).text)+'</p></div><span class="small" style="color:var(--cream)">58 mục tra cứu · 5 phần nội dung</span></section><section class="welcome-form"><img class="form-logo" src="'+ASSETS.logoColor+'" alt="IPA Group"><span class="eyebrow">CHÀO MỪNG ĐẾN VỚI IPAG GLOSSARY</span><h2>Bắt đầu với bạn</h2><p class="lead">Cho chúng tôi biết tên để đồng hành cùng bạn trong hành trình đọc và khám phá.</p><form id="profile-form">'+profileFields()+'<button class="btn" type="submit">Bắt đầu khám phá '+ico('arrow')+'</button></form><p class="personal-notice">Tên và tiến độ chỉ được lưu trên trình duyệt này.</p></section></div>'}
function shell(content){const count=DATA.terms.filter(t=>hasSaved(t.id)).length;return '<div class="layout '+(settings.collapsed?'collapsed ':'')+(s.selected&&['lookup','saved'].includes(s.view)?'detail-mode':'lookup-mode')+'" id="layout"><aside class="sidebar" id="sidebar" aria-label="Menu chính"><div class="identity"><button class="brand-button" data-view="home" aria-label="IPA Group — về trang chủ"><img src="'+ASSETS.logoWhite+'" alt="IPA Group"></button><span class="sub">IPAG GLOSSARY</span><button class="icon-btn menu-close" data-action="menu" aria-label="Đóng menu">'+ico('close')+'</button></div><nav class="nav">'+VIEWS.map(([v,i,l])=>'<button data-view="'+v+'" '+(s.view===v?'aria-current="page"':'')+'>'+ico(i)+l+(v==='saved'?'<span class="badge">'+count+'</span>':'')+'</button>').join('')+'</nav><div class="side-label">Khám phá 5 phần</div><nav class="section-nav" aria-label="Năm phần Glossary">'+DATA.sections.map(x=>'<button data-section="'+x.id+'"><span class="roman">'+x.roman+'</span>'+x.id+'<span class="count">'+x.count+'</span></button>').join('')+'</nav><div class="side-bottom"><div>'+esc(name())+' đã đọc '+read.size+'/58 mục</div><div class="bar" role="progressbar" aria-label="Tiến độ đọc" aria-valuemin="0" aria-valuemax="58" aria-valuenow="'+read.size+'"><span style="width:'+read.size/58*100+'%"></span></div><button data-action="about">Thông tin & hướng dẫn</button></div></aside><div class="scrim" id="scrim" data-action="close-menu"></div><div class="shell"><header class="topbar"><div class="breadcrumb"><button class="icon-btn menu-open" id="menu-toggle" data-action="menu" aria-label="Đóng hoặc mở menu" aria-controls="sidebar" aria-expanded="'+(!settings.collapsed&&window.innerWidth>850)+'">'+ico('menu')+'</button><strong>'+esc(VIEWS.find(v=>v[0]===s.view)?.[2]||'Glossary')+'</strong></div><div class="tools"><span class="version">Nội dung v2.0 · 10/2026</span><button class="icon-btn" data-action="settings" aria-label="Cài đặt" title="Cài đặt">'+ico('settings')+'</button><button class="profile-pill" data-action="profile" aria-label="Sửa tên và avatar của '+esc(profile.fullName)+'">'+avatar(profile.avatar)+'<span>'+esc(name())+'</span></button></div></header><main id="main" class="main" tabindex="-1">'+content+'</main></div></div>'}
function searchForm(home=false){return '<form class="global-search" id="search-form" role="search"><div class="searchbox">'+ico('search')+'<input id="search-input" type="search" role="combobox" aria-autocomplete="list" aria-haspopup="listbox" autocomplete="off" placeholder="Tìm thuật ngữ, tên đầy đủ hoặc nội dung…" aria-label="Tra cứu Glossary" aria-controls="suggestions" aria-expanded="false" value="'+esc(s.q)+'"><button type="button" class="icon-btn" data-action="clear-search" aria-label="Xóa tìm kiếm" '+(!s.q?'hidden':'')+'>'+ico('close')+'</button><button class="btn search-submit" type="submit">Tìm kiếm</button></div><div class="suggestions" id="suggestions" role="listbox" aria-label="Gợi ý thuật ngữ" hidden></div></form><p class="search-help">Tìm có hoặc không dấu · Nhấn Enter để xem kết quả'+(home?' · Ví dụ: OC, COL, SBI':'')+'</p>'}
function home(){return '<section class="hero"><img class="hero-bg" src="'+ASSETS.building+'" alt=""><div class="hero-copy"><span class="eyebrow">IPAG GROUP · BỘ TỪ ĐIỂN THUẬT NGỮ</span><p class="hello">Chào '+esc(name())+',</p><h1>Hôm nay bạn muốn<br>hiểu thuật ngữ nào?</h1><p>'+esc(DATA.source.find(p=>p.index===3).text)+'</p></div><div class="hero-stats"><div class="stat"><strong>58</strong><span>mục tra cứu</span></div><div class="stat"><strong>05</strong><span>phần nội dung</span></div></div></section><section class="home-search" aria-label="Tìm kiếm">'+searchForm(true)+'</section>'+(recent.length?'<div class="section-head"><h2>'+esc(name())+' vừa xem</h2></div><div class="recent-row">'+recent.slice(0,6).map(id=>'<button data-term="'+id+'">'+esc(termMap.get(id).key)+' '+ico('right')+'</button>').join('')+'</div>':'')+'<div class="section-head"><h2>Khám phá theo từng phần</h2><p>Chọn một phần để bắt đầu</p></div><section class="cards">'+DATA.sections.map(x=>'<button class="section-card" data-section="'+x.id+'"><span class="card-top"><span class="card-num">'+x.roman+'</span><span>'+x.count+' mục tra cứu</span></span><h3>'+x.id+'</h3><p>'+esc(x.description)+'</p><span class="arrow">'+ico('arrow')+'</span></button>').join('')+'<div class="intro-tile"><span class="eyebrow">VỀ BỘ TỪ ĐIỂN</span><p>'+esc(DATA.source.find(p=>p.index===16).text)+'</p><button class="btn ghost" data-view="reading">Đọc lời mở đầu '+ico('arrow')+'</button></div></section>'+footer()}
function filterHTML(){const available=new Set(DATA.terms.map(t=>/^\d/.test(t.key)?'#':t.key[0].toUpperCase()));return '<div class="filters" aria-label="Lọc theo phần">'+[['all','Tất cả'],...DATA.sections.map(x=>[x.id,x.id])].map(([v,l])=>'<button class="chip" data-filter="'+v+'" aria-pressed="'+(s.section===v)+'">'+l+'</button>').join('')+'</div><div class="alpha-nav" aria-label="Tra theo chữ cái"><button style="width:46px" data-alpha="all" aria-pressed="'+(s.alpha==='all')+'">A–Z</button>'+['#',...'ABCDEFGHIJKLMNOPQRSTUVWXYZ'].map(c=>'<button data-alpha="'+c+'" aria-pressed="'+(s.alpha===c)+'" '+(!available.has(c)?'disabled':'')+'>'+c+'</button>').join('')+'</div>'}
function snippet(t,q){const all=t.paragraphs.map(p=>p.text).join(' ');if(!q.trim())return all.slice(0,132)+(all.length>132?'…':'');const matches=searchRanges(all,q);const start=Math.max(0,(matches[0]?.start||0)-42),end=Math.min(all.length,start+170);return(start?'…':'')+all.slice(start,end)+(end<all.length?'…':'')}
function termRow(r){const t=r.t,id=t.id;return '<button class="term-row" data-term="'+id+'" aria-current="'+((s.selected||s.previewId)===id)+'"><span class="term-key">'+simpleHighlight(t.key)+'</span><span class="term-sub">'+simpleHighlight(t.title)+'</span><span class="term-snippet">'+simpleHighlight(snippet(t,s.q))+'</span><span class="term-meta"><span>'+t.section+'</span>'+(read.has(id)?'<span>✓ Đã đọc</span>':'')+(notes[id].length?'<span>'+notes[id].length+' ghi chú</span>':'')+(highlights[id].length?'<span>'+highlights[id].length+' highlight</span>':'')+(s.q?'<span class="match-tag">'+r.label+'</span>':'')+'</span>'+(bookmarks.has(id)?'<span class="flag">'+ico('bookmark')+'</span>':'')+(s.view==='saved'&&notes[id].length?'<span class="saved-snippet">Ghi chú: '+esc(notes[id][0].text.slice(0,150))+(notes[id][0].text.length>150?'…':'')+'</span>':'')+(s.view==='saved'&&highlights[id].length?'<span class="saved-snippet">Đã tô: “'+esc(highlights[id][0].quote.slice(0,110))+'”</span>':'')+'</button>'}
function lookup(){const rs=results(),selected=s.selected?termMap.get(s.selected):!mobile()?rs[0]?.t:null,isSaved=s.view==='saved';if(selected&&!s.selected&&!mobile())s.previewId=selected.id;else s.previewId=null;return '<div class="lookup-head"><div class="page-title"><div><span class="eyebrow">'+(isSaved?'KHÔNG GIAN CÁ NHÂN':'BỘ TỪ ĐIỂN THUẬT NGỮ')+'</span><h1>'+(isSaved?'Đã lưu & ghi chú của '+esc(name()):'Tra cứu thuật ngữ')+'</h1><p>'+(isSaved?'Thuật ngữ, đoạn highlight và suy nghĩ bạn muốn giữ lại.':'Tìm đúng thuật ngữ. Đọc đầy đủ. Kết nối các khái niệm.')+'</p></div></div>'+searchForm()+filterHTML()+(isSaved?'<div class="saved-filters">'+[['all','Tất cả'],['bookmarks','Đã lưu'],['notes','Có ghi chú'],['highlights','Có highlight']].map(([v,l])=>'<button class="chip" data-saved-filter="'+v+'" aria-pressed="'+(s.savedFilter===v)+'">'+l+'</button>').join('')+'</div>':'')+'<div class="result-tools"><span role="status">'+rs.length+' mục'+(s.q?' cho “'+esc(s.q)+'”':'')+'</span>'+(s.q?'<span class="hint">Ưu tiên tên thuật ngữ → tiêu đề → giải thích</span>':'<label>Sắp xếp <select id="sort"><option value="source" '+(s.sort==='source'?'selected':'')+'>Theo tài liệu</option><option value="az" '+(s.sort==='az'?'selected':'')+'>A → Z</option></select></label>')+'</div></div><section class="explorer"><div class="term-list" id="term-list">'+(rs.length?rs.map(termRow).join(''):emptyResults())+'</div>'+(selected?detail(selected):'<article class="detail empty"><h2>Chọn một thuật ngữ</h2><p>Phần giải thích đầy đủ sẽ xuất hiện tại đây.</p></article>')+'</section><div class="lookup-foot">'+footer()+'</div>'}
function emptyResults(){return '<div class="empty"><h2>'+(s.view==='saved'&&!DATA.terms.some(t=>hasSaved(t.id))?'Chưa có nội dung được lưu':'Chưa tìm thấy kết quả')+'</h2><p>'+(s.view==='saved'?'Bạn có thể lưu thuật ngữ, tô một đoạn hoặc thêm ghi chú.':'Thử tên viết tắt, bớt một từ hoặc mở rộng sang tất cả các phần.')+'</p><div class="actions"><button class="btn ghost" data-action="reset-filters">Xóa bộ lọc</button><button class="btn ghost" data-action="all-results">Tìm trong toàn bộ Glossary</button></div></div>'}
function activeTerm(){return termMap.get(s.selected||s.previewId)}
function detail(t){const id=t.id,sec=DATA.sections.find(x=>x.id===t.section),related=[...new Set(t.paragraphs.flatMap(p=>linkedRanges(p.text,id).map(x=>x.id)))];return '<article class="detail" id="detail" data-term-id="'+id+'"><div class="detail-top"><button class="detail-back" data-action="back-results">'+ico('left')+' Quay lại '+(s.depth>0?'vị trí trước':'kết quả')+'</button><div class="detail-meta"><span class="part-label">Phần '+sec.roman+' · '+sec.id+'</span><button class="icon-btn" data-bookmark="'+id+'" aria-pressed="'+bookmarks.has(id)+'" aria-label="'+(bookmarks.has(id)?'Bỏ lưu':'Lưu thuật ngữ')+'">'+ico('bookmark')+'</button></div><h2 id="detail-title" tabindex="-1">'+simpleHighlight(t.key)+'</h2><p class="detail-original-title" data-source-index="'+id.slice(5)+'">'+simpleHighlight(t.title)+'</p><div class="detail-actions"><button class="btn ghost" data-action="copy-link">'+ico('link')+' Sao chép liên kết</button><button class="btn ghost" data-action="add-note">'+ico('note')+' Ghi chú</button><button class="btn ghost" data-action="compare-term">'+ico('compare')+' So sánh</button></div></div><div class="detail-body" id="detail-body">'+t.paragraphs.map(p=>para(p,{id,links:true,annotations:true,query:s.q})).join('')+'</div><div class="annotation-tools no-selection" id="annotation-tools"><p><b>Highlight & ghi chú</b> · Bôi chọn một đoạn trong giải thích.</p><div class="color-options">'+Object.entries(COLORS).map(([c,l])=>'<button class="color-dot color-'+c+'" data-color="'+c+'" aria-label="Tô màu '+l+'" title="Tô màu '+l+'"></button>').join('')+'<button class="text-btn" data-action="note-selection">Ghi chú đoạn đã chọn</button></div><div class="selection-note" id="selection-status" role="status">Chưa chọn đoạn văn.</div></div>'+(related.length?'<div class="detail-related">Thuật ngữ được nhắc trong nội dung<div>'+related.map(x=>'<button class="chip" data-term="'+x+'">'+esc(termMap.get(x).key)+'</button>').join('')+'</div>':'')+annotationHTML(id)+'<div class="detail-footer"><button class="btn '+(read.has(id)?'ghost':'')+'" data-read="'+id+'" aria-pressed="'+read.has(id)+'">'+ico('check')+(read.has(id)?'Đã đánh dấu đọc':'Đánh dấu đã đọc')+'</button><button class="text-btn" data-action="feedback">'+ico('flag')+' Báo nội dung chưa rõ</button></div></article>'}
function annotationHTML(id){if(!notes[id].length&&!highlights[id].length)return '';return '<section class="annotation-section"><h3>Ghi chú & highlight của '+esc(name())+'</h3>'+notes[id].map(n=>'<article class="annotation-item">'+(n.quote?'<p class="quote">'+esc(n.quote)+'</p>':'')+'<p>'+esc(n.text)+'</p><div class="meta"><span>Ghi chú cá nhân</span><span><button class="text-btn" data-edit-note="'+n.id+'">Sửa</button><button class="text-btn" data-delete-note="'+n.id+'">Xóa</button></span></div></article>').join('')+highlights[id].map(h=>'<article class="annotation-item"><p class="quote"><mark class="user-highlight '+h.color+'">'+esc(h.quote)+'</mark></p><div class="meta"><span>Highlight · '+COLORS[h.color]+'</span><button class="text-btn" data-delete-highlight="'+h.id+'">Xóa highlight</button></div></article>').join('')+'</section>'}
function reading(){return '<div class="page-title"><div><span class="eyebrow">ĐỌC THEO PHẦN</span><h1>Toàn bộ nội dung Glossary</h1><p>'+esc(name())+' có thể đọc tuần tự hoặc chọn một phần.</p></div><button class="btn ghost" data-action="print">'+ico('print')+' In tài liệu</button></div><div class="reading-layout"><article class="reading-paper">'+SOURCE_HTML+'</article><aside class="reading-aside"><span class="eyebrow">MỤC LỤC</span><button class="text-btn" data-scroll="main">Lời mở đầu</button>'+DATA.sections.map((x,i)=>'<a href="#source-'+[18,57,120,140,184][i]+'" data-scroll="source-'+[18,57,120,140,184][i]+'">'+x.roman+'. '+x.id+'</a>').join('')+'</aside></div>'+footer()}
let compareIds=['term-66','term-68'];
function compare(){return '<div class="page-title"><div><span class="eyebrow">ĐẶT CẠNH NHAU ĐỂ ĐỐI CHIẾU</span><h1>So sánh hai thuật ngữ</h1><p>Hai phần giải thích nguyên văn từ Glossary.</p></div></div><div class="compare-grid">'+compareIds.map((id,i)=>{const t=termMap.get(id);return '<article class="compare-pane"><label class="field" for="compare-'+i+'">Thuật ngữ '+(i+1)+'</label><select class="select" id="compare-'+i+'" data-compare="'+i+'">'+DATA.terms.map(x=>'<option value="'+x.id+'" '+(x.id===id?'selected':'')+'>'+esc(x.title)+'</option>').join('')+'</select><span class="part-label">'+t.section+'</span><h2>'+esc(t.title)+'</h2>'+t.paragraphs.map(p=>para(p)).join('')+'<button class="btn ghost" data-term="'+id+'">Mở thuật ngữ '+ico('arrow')+'</button></article>'}).join('')+'</div>'+footer()}
let session={ids:[],index:0,flipped:false,answers:{},complete:false,filter:'all',savedOnly:false,consecutive:0};
function startSession(keep=true,ids=null){answerHistory=[];const filter=keep?session.filter:'all',savedOnly=keep?session.savedOnly:false;session={ids:ids||DATA.terms.filter(t=>(filter==='all'||t.section===filter)&&(!savedOnly||hasSaved(t.id))).map(t=>t.id),index:0,flipped:false,answers:{},complete:false,filter,savedOnly,consecutive:0};busy=false}
function localDate(d=new Date()){return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function streak(){const set=new Set(studyDays);let d=new Date();d.setHours(12,0,0,0);if(!set.has(localDate(d)))d.setDate(d.getDate()-1);let n=0;while(set.has(localDate(d))){n++;d.setDate(d.getDate()-1)}return n}
function study(){if(!session.ids.length&&!session.savedOnly&&session.filter==='all')startSession();return '<div class="study-shell"><div class="page-title"><div><span class="eyebrow">THẺ ÔN TẬP CỦA '+esc(name().toUpperCase())+'</span><h1>Mỗi lần, một thuật ngữ</h1><p>Thử nhớ ý nghĩa, lật thẻ rồi tự đánh giá.</p></div><button class="icon-btn" data-action="settings" aria-label="Cài đặt âm thanh, rung và chuyển động">'+ico('settings')+'</button></div><div class="study-controls"><label class="small">Phạm vi <select class="select" id="study-filter"><option value="all">Tất cả 5 phần</option>'+DATA.sections.map(x=>'<option value="'+x.id+'" '+(session.filter===x.id?'selected':'')+'>'+x.id+'</option>').join('')+'</select></label><label class="small"><input type="checkbox" id="study-saved" '+(session.savedOnly?'checked':'')+'> Chỉ nội dung đã lưu</label><button class="btn ghost" data-action="shuffle">'+ico('shuffle')+' Trộn thẻ</button></div><div id="study-body">'+studyBody()+'</div><div class="study-options"><span>'+streak()+' ngày ôn liên tiếp · '+known.size+'/58 mục tự đánh giá đã nhớ</span><button class="text-btn" data-action="toggle-audio">Âm thanh: '+(settings.audio?'Bật':'Tắt')+'</button></div><p class="study-session-note">Kết quả tự đánh giá của bạn, chưa phải xác nhận hoàn thành trên LMS.</p></div>'+footer()}
function studyBody(){if(!session.ids.length)return '<div class="empty"><h2>Chưa có thẻ trong phạm vi này</h2><p>Bỏ bộ lọc hoặc lưu thêm thuật ngữ, highlight, ghi chú.</p></div>';if(session.complete){const k=Object.values(session.answers).filter(x=>x==='known').length,r=Object.values(session.answers).filter(x=>x==='review').length;return '<section class="session-complete"><span class="big-check">'+ico('check')+'</span><span class="eyebrow">HOÀN TẤT LƯỢT ÔN</span><h2>'+esc(name())+' đã đi qua '+session.ids.length+' thẻ!</h2><p>Đây là mức độ ghi nhớ bạn vừa tự đánh giá.</p><div class="session-numbers"><div><strong>'+k+'</strong><span>Đã nhớ</span></div><div><strong>'+r+'</strong><span>Cần xem lại</span></div></div><div class="actions">'+(r?'<button class="btn" data-action="review-again">Ôn '+r+' thẻ cần xem lại</button>':'')+'<button class="btn ghost" data-action="restart-study">Ôn lại bộ thẻ</button><button class="btn ghost" data-view="home">Về trang chủ</button></div></section>'}const t=termMap.get(session.ids[session.index]),done=Object.keys(session.answers).length;return '<div class="study-controls"><span class="study-status">Thẻ <strong>'+(session.index+1)+' / '+session.ids.length+'</strong> · '+t.section+'</span><span class="study-status" role="status">Đã tự đánh giá '+done+'/'+session.ids.length+(session.consecutive>=2?' · Chuỗi '+session.consecutive+' thẻ đã nhớ':'')+'</span></div><div class="study-progress '+(session.consecutive>=2?'pulse':'')+'" role="progressbar" aria-label="Tiến độ lượt ôn" aria-valuemin="0" aria-valuemax="'+session.ids.length+'" aria-valuenow="'+done+'"><span style="width:'+done/session.ids.length*100+'%"></span></div><div class="study-ambient"><div class="deck" id="deck"><div class="stack-layer second"></div><div class="stack-layer"></div><div class="card-drag" id="card-drag"><span class="swipe-label know" id="swipe-know">ĐÃ NHỚ</span><span class="swipe-label review" id="swipe-review">CẦN XEM LẠI</span><button class="icon-btn card-expand" data-action="expand-card" aria-label="Mở rộng thẻ">'+ico('expand')+'</button><div class="flip-inner '+(session.flipped?'flipped':'')+'" id="flip-inner"><div class="card-face card-front" id="card-front" role="button" tabindex="'+(session.flipped?'-1':'0')+'" aria-label="'+esc(t.title)+' — lật để xem giải thích" aria-hidden="'+session.flipped+'" data-action="flip"><span class="eyebrow">BẠN HIỂU THUẬT NGỮ NÀY THẾ NÀO?</span><h2>'+esc(t.title)+'</h2><span class="hint">'+ico('flip')+' Nhấn để lật thẻ</span></div><div class="card-face card-back" id="card-back" tabindex="'+(session.flipped?'0':'-1')+'" aria-hidden="'+(!session.flipped)+'"><span class="eyebrow">PHẦN GIẢI THÍCH NGUYÊN VĂN</span><h2>'+esc(t.title)+'</h2>'+t.paragraphs.map(p=>para(p)).join('')+'</div></div></div></div><div class="study-actions"><button class="btn ghost" data-answer="review">'+ico('left')+' Cần xem lại</button><button class="btn ghost" data-action="flip">'+ico('flip')+' Lật thẻ</button><button class="btn" data-answer="known">Đã nhớ '+ico('right')+'</button></div><div class="study-options"><span>Vuốt trái: cần xem lại · Vuốt phải: đã nhớ</span><button class="text-btn" data-action="undo-answer" '+(!done?'disabled':'')+'>Hoàn tác lần gần nhất</button></div></div>'}
let audioContext=null;
function feedbackFX(kind){if(settings.haptics&&typeof navigator.vibrate==='function'){try{navigator.vibrate(kind==='complete'?[18,40,18]:8)}catch(e){}}if(!settings.audio)return;try{audioContext=audioContext||new(window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();const now=audioContext.currentTime;const frequencies=kind==='complete'?[523,659,784]:[kind==='known'?660:kind==='flip'?400:300];frequencies.forEach((freq,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(.0001,now+i*.1);g.gain.exponentialRampToValueAtTime(.045,now+i*.1+.012);g.gain.exponentialRampToValueAtTime(.0001,now+i*.1+.15);o.connect(g);g.connect(audioContext.destination);o.start(now+i*.1);o.stop(now+i*.1+.17)})}catch(e){}}
function flipCard(){if(busy||session.complete||!session.ids.length)return;session.flipped=!session.flipped;const inner=$('flip-inner');if(!inner)return;inner.classList.toggle('flipped',session.flipped);for(const [id,shown]of[['card-front',!session.flipped],['card-back',session.flipped]]){$(id).setAttribute('aria-hidden',String(!shown));$(id).tabIndex=shown?0:-1}$(session.flipped?'card-back':'card-front').focus({preventScroll:true});feedbackFX('flip')}
let answerHistory=[];
function answerCard(value){if(busy||session.complete||!session.ids.length)return;busy=true;const activeSession=session,id=session.ids[session.index];answerHistory.push({id,index:session.index,oldKnown:known.has(id),oldBookmark:bookmarks.has(id),previous:session.answers[id],consecutive:session.consecutive});session.answers[id]=value;if(value==='known'){known.add(id);session.consecutive++}else{known.delete(id);bookmarks.add(id);session.consecutive=0}persist();feedbackFX(value);const card=$('card-drag');if(card&&!reduced()){card.classList.add('leaving');card.style.transform='translateX('+(value==='known'?1:-1)*420+'px) rotate('+(value==='known'?16:-16)+'deg)'}setTimeout(()=>{if(s.view!=='study'||session!==activeSession){busy=false;return}session.index++;session.flipped=false;if(session.index>=session.ids.length){session.complete=true;studyDays=[...new Set([...studyDays,localDate()])].slice(-400);persist();feedbackFX('complete');confetti()}busy=false;renderStudy()},reduced()?0:300)}
function renderStudy(){if($('study-body')){$('study-body').innerHTML=studyBody();installSwipe();const area=$('study-body');area.setAttribute('aria-live','polite')}}
function confetti(){if(reduced())return;const colors=['#59798F','#C4AA78','#D0BB93','#3E5B6C'];$('confetti').innerHTML=Array.from({length:32},(_,i)=>'<i class="confetti-piece" style="left:'+(Math.random()*100)+'%;background:'+colors[i%4]+';--dx:'+(Math.random()*200-100)+'px;animation-delay:'+(Math.random()*.5)+'s"></i>').join('');setTimeout(()=>$('confetti').innerHTML='',3500)}
let suppressClickUntil=0;
function installSwipe(){const card=$('card-drag');if(!card)return;let drag=null;card.onpointerdown=e=>{if(busy||e.button!==0||e.target.closest('button,a,input,textarea,select'))return;drag={x:e.clientX,y:e.clientY,time:performance.now(),dx:0,active:false,pointer:e.pointerId}};card.onpointermove=e=>{if(!drag||e.pointerId!==drag.pointer)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!drag.active&&Math.abs(dy)>18&&Math.abs(dy)>Math.abs(dx)){drag=null;return}if(!drag.active&&Math.abs(dx)>12&&Math.abs(dx)>Math.abs(dy)*1.3){drag.active=true;card.setPointerCapture(e.pointerId);card.classList.add('dragging')}if(drag.active){drag.dx=dx;card.style.transform='translateX('+dx+'px) rotate('+dx/20+'deg)';$('swipe-know').style.opacity=dx>0?Math.min(dx/100,1):0;$('swipe-review').style.opacity=dx<0?Math.min(-dx/100,1):0}};function release(e,cancel=false){if(!drag)return;const d=drag;drag=null;card.classList.remove('dragging');if(d.active){suppressClickUntil=Date.now()+500;const speed=Math.abs(d.dx)/Math.max(performance.now()-d.time,1);if(!cancel&&(Math.abs(d.dx)>85||Math.abs(d.dx)>35&&speed>.6)){answerCard(d.dx>0?'known':'review');return}}card.style.transform='';if($('swipe-know'))$('swipe-know').style.opacity=0;if($('swipe-review'))$('swipe-review').style.opacity=0}card.onpointerup=e=>release(e);card.onpointercancel=e=>release(e,true)}
function render(){document.body.classList.toggle('no-motion',!settings.motion);if(!profile){$('app').innerHTML=gate();return}const html=s.view==='home'?home():s.view==='reading'?reading():s.view==='compare'?compare():s.view==='study'?study():lookup();$('app').innerHTML=shell(html);if(window.innerWidth<=850)$('sidebar').inert=true;else $('sidebar').inert=settings.collapsed;if(s.view==='study')installSwipe();draft=s.q}
