function about(){modalContext={type:'about'};showModal('Thông tin & hướng dẫn','<p><b>Tra cứu:</b> nhập thuật ngữ rồi nhấn Enter. Kết quả ưu tiên tên viết tắt, tiêu đề, sau đó đến giải thích. Hỗ trợ tìm không dấu và gợi ý lỗi gõ nhỏ với từ dài.</p><p><b>Ghi chú:</b> bôi chọn một đoạn trong phần giải thích, chọn màu hoặc thêm ghi chú. Mục Đã lưu & ghi chú tập hợp tất cả nội dung cá nhân.</p><p><b>Tự ôn:</b> lật thẻ bằng nút hoặc phím Space/Enter khi thẻ được chọn; vuốt hoặc bấm Đã nhớ/Cần xem lại. Âm thanh có thể bật trong cài đặt.</p><p><b>Nội dung:</b> Glossary IPAG_15102026 2.docx, phiên bản 2.0, tháng 10/2026. Giữ nguyên nội dung và cách viết trong nguồn. Ghi chú cá nhân không sửa nội dung Glossary.</p><p><b>Chia sẻ:</b> khi chạy trên GitHub Pages, mỗi thuật ngữ có liên kết trực tiếp. Với bản offline, bạn có thể gửi file cùng tên/mã thuật ngữ.</p><p class="modal-copy">Ứng dụng 3.0 · cập nhật 15/10/2026. Dữ liệu lưu tại trình duyệt, chưa đồng bộ thiết bị hay LMS. Chưa đóng gói SCORM.</p>')}
function captureSelection(){const sel=window.getSelection(),body=$('detail-body');if(!sel||sel.isCollapsed||!sel.rangeCount||!body)return;const range=sel.getRangeAt(0);if(!body.contains(range.startContainer)||!body.contains(range.endContainer))return;const found=[];for(const p of body.querySelectorAll('[data-annotatable]')){if(!range.intersectsNode(p))continue;let start=0,end=p.textContent.length;if(p.contains(range.startContainer)){const before=document.createRange();before.selectNodeContents(p);before.setEnd(range.startContainer,range.startOffset);start=before.toString().length}if(p.contains(range.endContainer)){const before=document.createRange();before.selectNodeContents(p);before.setEnd(range.endContainer,range.endOffset);end=before.toString().length}if(end>start&&p.textContent.slice(start,end).trim())found.push({p:Number(p.dataset.annotatable),start,end,quote:p.textContent.slice(start,end)})}if(found.length){selectionParts=found;$('selection-status').textContent='Đã chọn: “'+found.map(x=>x.quote).join(' ').slice(0,110)+'”';$('annotation-tools').classList.remove('no-selection')}}
function addHighlight(color){const t=activeTerm();if(!t)return;if(!selectionParts.length){toast('Bôi chọn đoạn trong giải thích trước khi chọn màu.');return}for(const part of selectionParts){const existing=highlights[t.id].find(h=>h.p===part.p&&h.start===part.start&&h.end===part.end);if(existing)existing.color=color;else highlights[t.id].push({id:uid(),...part,color,created:new Date().toISOString()})}const ok=persist();window.getSelection()?.removeAllRanges();refreshDetail();if(ok)toast('Đã lưu highlight màu '+COLORS[color].toLowerCase()+'.')}
function noteModal(existing=null,useSelection=false){const t=activeTerm();if(!t)return;if(useSelection&&!selectionParts.length){toast('Bôi chọn một đoạn trước khi thêm ghi chú cho đoạn đó.');return}const quote=existing?.quote||(useSelection?selectionParts.map(x=>x.quote).join('\n'):'');modalContext={type:'note',termId:t.id,noteId:existing?.id||null,quote,initial:existing?.text||''};showModal(existing?'Sửa ghi chú':'Ghi chú cho '+esc(t.key),'<p class="modal-title-small">Ghi chú cá nhân của '+esc(name())+'</p>'+(quote?'<div class="quote-preview">'+esc(quote)+'</div>':'')+'<form id="note-form"><label class="field" for="note-text">Nội dung ghi chú</label><textarea class="input" id="note-text" maxlength="10000" required placeholder="Điều bạn muốn nhớ hoặc liên hệ với công việc…">'+esc(existing?.text||'')+'</textarea><div class="modal-actions"><button class="btn ghost" type="button" data-action="close-modal">Hủy</button><button class="btn" type="submit">Lưu ghi chú</button></div></form>');$('note-text').focus()}
async function copyText(text,success='Đã sao chép.'){try{if(!navigator.clipboard?.writeText)throw new Error('unavailable');await navigator.clipboard.writeText(text);toast(success);return true}catch(e){const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.left='-9999px';document.body.append(ta);ta.select();let done=false;try{done=document.execCommand('copy')}catch(e){}ta.remove();if(done){toast(success);return true}modalContext={type:'copy'};showModal('Sao chép nội dung','<p class="modal-copy">Trình duyệt chưa cho phép sao chép tự động. Chọn nội dung bên dưới và nhấn Ctrl+C hoặc giữ để sao chép.</p><textarea class="input link-fallback" id="copy-value" readonly>'+esc(text)+'</textarea>');$('copy-value').select();return false}}
