document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName);if(e.key==='Escape'){if($('modal').open){e.preventDefault();closeModal();return}closeMenu();if($('suggestions')){$('suggestions').hidden=true;$('search-input').setAttribute('aria-expanded','false')}return}if(e.target.id==='search-input'&&['ArrowDown','ArrowUp'].includes(e.key)){const opts=[...($('suggestions')?.querySelectorAll('[data-suggestion]')||[])];if(!opts.length||$('suggestions').hidden)return;e.preventDefault();suggestIndex=(suggestIndex+(e.key==='ArrowDown'?1:-1)+opts.length)%opts.length;opts.forEach((o,i)=>{o.classList.toggle('active',i===suggestIndex);o.setAttribute('aria-selected',String(i===suggestIndex))});$('search-input').setAttribute('aria-activedescendant','suggestion-'+suggestIndex);return}if(e.key==='/'&&!typing&&!$('modal').open&&profile){e.preventDefault();if(!['home','lookup','saved'].includes(s.view))navigate('lookup');$('search-input')?.focus();return}if(e.target.id==='card-front'||e.target.id==='card-back'){if(['Enter',' '].includes(e.key)){e.preventDefault();flipCard()}if(e.key==='ArrowRight'){e.preventDefault();answerCard('known')}if(e.key==='ArrowLeft'){e.preventDefault();answerCard('review')}}if(e.key==='Tab'&&window.innerWidth<=850&&$('sidebar')?.classList.contains('open')){const focusable=[...$('sidebar').querySelectorAll('button,a')],first=focusable[0],last=focusable.at(-1);if(e.shiftKey&&(document.activeElement===first||!$('sidebar').contains(document.activeElement))){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!$('sidebar').contains(document.activeElement))){e.preventDefault();first.focus()}}});
